const data=parse(fs.readFileSync(path.join(repo,'data.js'),'utf8')),declaration=(ast,name)=>ast.body.filter(n=>n.type==='VariableDeclaration').flatMap(n=>n.declarations).find(d=>d.id.name===name),types=Object.fromEntries(declaration(data,'TYPES_ORGANISATIONS').init.properties.map(p=>[p.key.name,Object.fromEntries(p.value.properties.filter(p=>['label','secret','requis','icon'].includes(p.key.name)).map(p=>[p.key.name,literal(p.value)]))])),options=literal(declaration(data,'GREVE_CORPS_METIER_OPTIONS').init);
