const cases=[{id:'type absent',mode:'form',type:'absent'},{id:'choix complet',mode:'choice'},{id:'type déjà fondé',mode:'choice',founded:['politique']},{id:'seule loge disponible',mode:'choice',founded:Object.keys(types).filter(t=>t!=='loge')},{id:'maximum',mode:'choice',founded:Object.keys(types)},{id:'autre empire',mode:'choice',founded:['politique'],origin:'soviet'},{id:'autre fondateur',mode:'choice',founded:['politique'],founder:'Autre PJ'},{id:'aucun prérequis',mode:'choice',requis:null}];for(const type of Object.keys(types))cases.push({id:'formulaire '+type,mode:'form',type});
